/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payment_transactions_before_insert` BEFORE INSERT ON `tb_payment_transactions` FOR EACH ROW BEGIN
    DECLARE v_payment_amount DECIMAL(12,2);

    SELECT amount
    INTO v_payment_amount
    FROM tb_payments
    WHERE ID = NEW.payment_ID;

    IF NEW.event_type IN ('Refunded', 'PartiallyRefunded') THEN

        IF NEW.amount > v_payment_amount THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El importe de la devolucion supera el importe del pago';
        END IF;

    END IF;

END */;;
