/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payments_after_insert` AFTER INSERT ON `tb_payments` FOR EACH ROW BEGIN
    INSERT INTO tb_payment_transactions (payment_ID, event_type, amount, event_reference, remarks)
    VALUES (NEW.ID, 'Created', NEW.amount, NEW.provider_reference, 'Pago creado');

    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_date, operation_description, operation_status)
    VALUES ('tb_payments', 'create', USER(), NOW(),
            CONCAT('ID: ', NEW.ID, ', order_ID: ', NEW.order_ID, ', amount: ', NEW.amount, ', status: ', NEW.payment_status),
            b'1');
END */;;
