/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payments_after_update` AFTER UPDATE ON `tb_payments` FOR EACH ROW BEGIN
    IF OLD.payment_status <> NEW.payment_status THEN
        INSERT INTO tb_payment_transactions (payment_ID, event_type, amount, event_reference, remarks)
        VALUES (
            NEW.ID,
            CASE NEW.payment_status
                WHEN 'Pending' THEN 'Created'
                WHEN 'Authorized' THEN 'Authorized'
                WHEN 'Paid' THEN 'Captured'
                WHEN 'Failed' THEN 'Failed'
                WHEN 'Cancelled' THEN 'Voided'
                WHEN 'Refunded' THEN 'Refunded'
                WHEN 'PartiallyRefunded' THEN 'PartiallyRefunded'
                ELSE 'Failed'
            END,
            NEW.amount,
            NEW.provider_reference,
            CONCAT('Cambio de estado: ', OLD.payment_status, ' -> ', NEW.payment_status)
        );
    END IF;

    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_date, operation_description, operation_status)
    VALUES ('tb_payments', 'update', USER(), NOW(),
            CONCAT('ID: ', NEW.ID, ', order_ID: ', NEW.order_ID, ', status: ', OLD.payment_status, ' -> ', NEW.payment_status),
            b'1');
END */;;
DELIMITER ;
