/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_before_insert` BEFORE INSERT ON `tb_people` FOR EACH ROW BEGIN
  SET NEW.given_names = TRIM(NEW.given_names);
  IF NEW.family_names IS NOT NULL THEN
    SET NEW.family_names = TRIM(NEW.family_names);
  END IF;

  IF NEW.country_code IS NOT NULL THEN
    SET NEW.country_code = UPPER(TRIM(NEW.country_code));
    IF LENGTH(NEW.country_code) <> 2 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Error: country_code debe tener exactamente 2 caracteres.';
    END IF;
  END IF;

  IF NEW.birth_date IS NOT NULL AND NEW.birth_date > CURDATE() THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Error: birth_date no puede ser una fecha futura.';
  END IF;
END */;;
DELIMITER ;
