/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_date, operation_description, operation_status)
    VALUES ('tb_people', 'create', USER(), NOW(),
            CONCAT('person_ID: ', NEW.person_ID, ', user_ID: ', IFNULL(NEW.user_ID, 'NULL'), ', nombre: ', NEW.given_names, ' ', IFNULL(NEW.family_names, '')),
            NEW.status);
END */;;
