/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_people_before_delete` BEFORE DELETE ON `tb_people` FOR EACH ROW BEGIN
  IF OLD.status = b'1' THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'Error: No se pueden eliminar físicamente registros activos. Cambia el status a 0 (borrado lógico).';
  END IF;
END */;;
