/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_users_after_insert` AFTER INSERT ON `tb_users` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name, 
        table_operation, 
        db_user, 
        operation_date, 
        operation_description, 
        operation_status
    )
    VALUES (
        'tb_users', 
        'create', 
        USER(), 
        NOW(), 
        CONCAT('Nuevo usuario registrado ID: ', NEW.ID, ' - Nick: ', NEW.nick), 
        NEW.status
    );
END */;;
