CREATE DEFINER=`root`@`localhost` FUNCTION `fn_random_birth_date`(p_min_age INT, p_max_age INT) RETURNS date
    NO SQL
BEGIN
    DECLARE v_min_a INT DEFAULT IFNULL(p_min_age, 18);
    DECLARE v_max_a INT DEFAULT IFNULL(p_max_age, 70);
    DECLARE v_tmp INT;
    DECLARE v_start_date DATE;
    DECLARE v_end_date DATE;
    DECLARE v_days_diff INT;

    IF v_min_a > v_max_a THEN
        SET v_tmp = v_min_a;
        SET v_min_a = v_max_a;
        SET v_max_a = v_tmp;
    END IF;

    SET v_end_date = DATE_SUB(CURDATE(), INTERVAL v_min_a YEAR);
    SET v_start_date = DATE_SUB(CURDATE(), INTERVAL (v_max_a + 1) YEAR);
    SET v_days_diff = GREATEST(DATEDIFF(v_end_date, v_start_date), 1);

    RETURN DATE_ADD(v_start_date, INTERVAL FLOOR(RAND() * v_days_diff) DAY);
END ;;
DELIMITER ;
