CREATE DEFINER=`root`@`localhost` FUNCTION `fn_random_gender`() RETURNS varchar(30) CHARSET utf8mb4
    NO SQL
BEGIN
    RETURN ELT(FLOOR(1 + RAND() * 3), 'Hombre', 'Mujer', 'Prefiero no decirlo');
END ;;
DELIMITER ;
