CREATE DEFINER=`root`@`localhost` FUNCTION `fn_random_status_bit`(p_active_prob DECIMAL(5,2)) RETURNS bit(1)
    NO SQL
BEGIN
    DECLARE v_prob DECIMAL(5,2) DEFAULT IFNULL(p_active_prob, 90.00);
    IF (RAND() * 100) < v_prob THEN
        RETURN b'1';
    ELSE
        RETURN b'0';
    END IF;
END ;;
DELIMITER ;
