CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_backfill_missing_people`()
    MODIFIES SQL DATA
BEGIN
    INSERT INTO tb_people (
        user_ID, courtesy_title, given_names, family_names,
        birth_date, gender, country_code, phone, status
    )
    SELECT
        u.ID,
        'Sr./Sra.',
        CONCAT('Usuario_', u.ID),
        'Simulado',
        fn_random_birth_date(18, 65),
        fn_random_gender(),
        fn_random_country_code(),
        CONCAT('+52 555-', LPAD(MOD(u.ID, 10000000), 7, '0')),
        u.status
    FROM tb_users u
    LEFT JOIN tb_people p ON p.user_ID = u.ID
    WHERE p.person_ID IS NULL;
END ;;
DELIMITER ;
