CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_synthetic_users`(
    IN p_quantity       INT,
    IN p_gender         VARCHAR(30),     -- NULL = aleatorio; 'Hombre', 'Mujer', 'Prefiero no decirlo'
    IN p_country_code   CHAR(2),         -- NULL = aleatorio; 'US', 'MX', etc.
    IN p_min_age        INT,             -- NULL = 18
    IN p_max_age        INT,             -- NULL = 70
    IN p_active_prob    DECIMAL(5,2)     -- NULL = 90.00 (% probabilidad status = b'1')
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_i             INT DEFAULT 0;
    DECLARE v_base_id       INT DEFAULT 0;
    DECLARE v_new_user_id   INT;
    DECLARE v_gender        VARCHAR(30);
    DECLARE v_country       CHAR(2);
    DECLARE v_birth         DATE;
    DECLARE v_status        BIT(1);
    DECLARE v_first_name    VARCHAR(150);
    DECLARE v_last_name     VARCHAR(150);
    DECLARE v_title         VARCHAR(20);
    DECLARE v_nick          VARCHAR(50);
    DECLARE v_email         VARCHAR(100);
    DECLARE v_phone         VARCHAR(25);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cantidad de usuarios debe ser mayor a 0';
    END IF;

    IF p_gender IS NOT NULL AND p_gender NOT IN ('Hombre', 'Mujer', 'Prefiero no decirlo') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Género no válido. Use Hombre, Mujer, Prefiero no decirlo o NULL';
    END IF;

    IF p_country_code IS NOT NULL AND UPPER(TRIM(p_country_code)) NOT REGEXP '^[A-Z]{2}$' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Código de país inválido (debe ser ISO de 2 letras o NULL)';
    END IF;

    SELECT IFNULL(MAX(ID), 0) INTO v_base_id FROM tb_users;

    START TRANSACTION;

    WHILE v_i < p_quantity DO
        SET v_i = v_i + 1;
        SET v_base_id = v_base_id + 1;

        SET v_gender  = COALESCE(p_gender, fn_random_gender());
        SET v_country = COALESCE(UPPER(TRIM(p_country_code)), fn_random_country_code());
        SET v_birth   = fn_random_birth_date(p_min_age, p_max_age);
        SET v_status  = fn_random_status_bit(p_active_prob);

        IF v_gender = 'Hombre' THEN
            SET v_title = 'Sr.';
            SET v_first_name = ELT(FLOOR(1 + RAND() * 12), 'Carlos', 'Juan', 'Luis', 'Miguel', 'José', 'Diego', 'Andrés', 'James', 'Michael', 'David', 'Daniel', 'Mateo');
        ELSEIF v_gender = 'Mujer' THEN
            SET v_title = 'Sra.';
            SET v_first_name = ELT(FLOOR(1 + RAND() * 12), 'María', 'Ana', 'Sofía', 'Laura', 'Elena', 'Valeria', 'Camila', 'Emma', 'Olivia', 'Sophia', 'Isabella', 'Lucía');
        ELSE
            SET v_title = NULL;
            SET v_first_name = ELT(FLOOR(1 + RAND() * 8), 'Alex', 'Taylor', 'Jordan', 'Sam', 'Morgan', 'Casey', 'Riley', 'Robin');
        END IF;

        SET v_last_name = CONCAT(
            ELT(FLOOR(1 + RAND() * 12), 'García', 'Rodríguez', 'Martínez', 'Hernández', 'López', 'González', 'Pérez', 'Smith', 'Johnson', 'Brown', 'Taylor', 'Miller'),
            ' ',
            ELT(FLOOR(1 + RAND() * 10), 'Cruz', 'Reyes', 'Morales', 'Ortiz', 'Gómez', 'Díaz', 'Silva', 'Vargas', 'Castro', 'Mendoza')
        );

        SET v_nick  = CONCAT('usr_', LOWER(v_country), '_', v_base_id, '_', FLOOR(100 + RAND() * 899));
        SET v_email = CONCAT(v_nick, '@simulated.test');
        SET v_phone = CONCAT('+52 ', FLOOR(100 + RAND() * 899), '-', FLOOR(100 + RAND() * 899), '-', FLOOR(1000 + RAND() * 8999));

        INSERT INTO tb_users (email, nick, password, status)
        VALUES (v_email, v_nick, SHA2(CONCAT('Pass#', v_base_id), 256), v_status);

        SET v_new_user_id = LAST_INSERT_ID();

        INSERT INTO tb_people (
            user_ID, courtesy_title, given_names, family_names,
            birth_date, gender, country_code, phone, status
        )
        VALUES (
            v_new_user_id, v_title, v_first_name, v_last_name,
            v_birth, v_gender, v_country, v_phone, v_status
        );
    END WHILE;

    COMMIT;

    SELECT CONCAT('Se generaron ', p_quantity, ' usuarios y personas exitosamente.') AS resultado;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
